/bin/zsh -lc "node test/regression.js
node <<'NODE'
const assert = require('node:assert/strict');
const { createProcessor } = require('./src/index');
const p = createProcessor();
const first = { id: 'one', amount: 100 };
const redelivery = { id: 'one', amount: 200 };
assert.notStrictEqual(first, redelivery);
const firstResult = p.process(first);
const duplicateResult = p.process(redelivery);
console.log(JSON.stringify({ firstResult, duplicateResult, ledger: p.ledger }));
assert.equal(duplicateResult, false, 'fresh object with the same ID must be rejected');
NODE"

